def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    rich_aggressive = 0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0.0)
                prev_bids.append(bid)
                if bid >= 90 and opp.get('budget', 0) >= 200:
                    rich_aggressive += 1

    if not alive:
        return float(min(budget, 18.0))

    tight_supply = supply <= 17
    ample_supply = supply >= 22

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water >= 2:
        urgency += 4
    elif no_water >= 1:
        urgency += 2
    if tight_supply:
        urgency += 2
    elif ample_supply:
        urgency -= 1
    urgency += min(desperate_count, 2)

    if urgency >= 7:
        base = 112.0
    elif urgency >= 5:
        base = 88.0
    elif urgency >= 3:
        base = 58.0
    else:
        base = 24.0

    if highest_prev >= 130:
        if urgency <= 2:
            base = min(base, 18.0)
        else:
            base = max(base, 96.0)
    elif highest_prev >= 100:
        if urgency <= 2:
            base = min(base, 22.0)
        else:
            base = max(base, 82.0)
    elif highest_prev >= 60:
        base = max(base, avg_prev + 3.0)
    elif highest_prev > 0:
        base = max(base, highest_prev + 2.0)

    if rich_aggressive >= 2 and urgency <= 3:
        base = min(base, 20.0)

    if day >= 8:
        base += 10.0
    elif day >= 5:
        base += 4.0

    if budget < 60:
        base = min(base, budget)
    elif budget < 140:
        base = min(base, 0.75 * budget)
    else:
        base = min(base, 0.55 * budget)

    floor_bid = 0.0
    if hp <= 2 or no_water >= 2:
        floor_bid = 45.0
    elif hp <= 4 or no_water >= 1:
        floor_bid = 28.0
    elif tight_supply:
        floor_bid = 18.0
    else:
        floor_bid = 10.0

    bid = max(base, floor_bid)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']

    alive = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive:
        return min(budget, DAILY_SALARY * 0.4)

    # Collect last bids from previous_trace
    last_bids = []
    for opp in alive.values():
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            last_bids.append(prev['bid'])

    # Determine number of winners based on supply
    num_winners = int(supply // WATER_REQ)  # floor division gives float, cast to int
    if num_winners == 0:
        num_winners = 1  # at least one water unit available (supply>=WATER_REQ? Actually supply range 15-25, so always at least 1)

    # Base bid amount
    if hp <= 3:
        # Need water urgently, bid aggressively
        bid = min(budget, DAILY_SALARY * 0.95)
    else:
        # Healthy, can try to save
        if last_bids:
            # Target a bid that beats the median of last bids to secure a slot
            sorted_bids = sorted(last_bids)
            # We want to be among top num_winners, so bid slightly above the (num_winners)-th highest
            if len(sorted_bids) >= num_winners:
                target = sorted_bids[-num_winners] * 1.05  # 5% over
            else:
                target = max(last_bids) * 1.05
            bid = min(budget, max(DAILY_SALARY * 0.5, target))
        else:
            bid = min(budget, DAILY_SALARY * 0.5)

    # Ensure bid is within budget and non-negative
    bid = max(0.0, min(float(budget), bid, 1000.0))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from immediate previous_trace only
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Pressure estimate: aggressive competitors likely continue bidding high
    aggressive = highest_prev_bid >= DAILY_SALARY * 0.85  # ~68

    # Supply pressure: if supply is high, we can bid less; if low, we must bid more
    # supply is in [15,25] but passed as float; use thresholds.
    if supply <= (MIN_SUPPLY + 1.0):
        supply_factor = 1.0
    elif supply >= (MAX_SUPPLY - 1.0):
        supply_factor = 0.65
    else:
        supply_factor = 0.85

    # If I'm in danger (multiple no-water days or low hp), bid to secure water.
    if my_hp <= 2 or my_no_water_days >= 2:
        base = DAILY_SALARY * (0.9 if aggressive else 0.75)
    elif my_hp <= 4:
        base = DAILY_SALARY * (0.75 if aggressive else 0.6)
    else:
        base = DAILY_SALARY * (0.6 if aggressive else 0.5)

    bid = base * supply_factor

    # If others were extremely high yesterday, cap my bid to avoid overpaying while still competing.
    if aggressive:
        bid = min(bid, DAILY_SALARY * 0.78)

    # Ensure non-negative and within budget.
    if my_budget <= 0:
        return 0.0
    if bid > my_budget:
        bid = my_budget

    # Add slight deterministic adjustment by day to avoid exact ties.
    bid += (float(day) % 3) * 0.5

    # Final clamp.
    if bid < 0:
        bid = 0.0
    return float(bid)
